local ECSComponent = import("Frame.ECS.ECSComponent")

---@class AccusationComponent
local AccusationComponent = Class("AccusationComponent", ECSComponent)

function AccusationComponent:__init()
    self.name = "AccusationComponent"
    self._allVo = CfUtils.GetCf(AutoIds.IdSetting6115, "AccusationVo", true)
end

function AccusationComponent:__delete()
end

--region public

function AccusationComponent:SwitchStatus()
    -- 切换页面的状态
    if not self:IsStateValid() then return end

    local newState = {
        [Constants.PAGE_STATES.CHOOSE_TYPE] = Constants.PAGE_STATES.FILL_DETAILS,
        [Constants.PAGE_STATES.FILL_DETAILS] = Constants.PAGE_STATES.CHOOSE_TYPE
    }
    self:TransferStateTo(newState[self._state])
end
--endregion public

--region private
---@param state integer
function AccusationComponent:TransferStateTo(state)
    self._state = state
    Events.Broadcast("SHOW_ACCUSATION_PAGE", self._state)
end

function AccusationComponent:IsStateValid()
    self._state = checkNumber(self._state)
    return (self._state == Constants.PAGE_STATES.CHOOSE_TYPE) or (self._state == Constants.PAGE_STATES.FILL_DETAILS)
end

function AccusationComponent:GetVoList()
    return self._allVo
end

function AccusationComponent:DeActiveCheckStatus()
    for _, vo in ipairs(checkTable(self._allVo)) do
        vo.isChecked = false
    end
end
--endregion private

return AccusationComponent